// Minimal stdio MCP client: spawns the gbrain server exactly as registered in OpenClaw config.
import { spawn } from 'node:child_process';
import { execFileSync } from 'node:child_process';
const cfg = JSON.parse(execFileSync('openclaw', ['config', 'get', 'mcp.servers.gbrain', '--json'], { encoding: 'utf8' }).match(/\{[\s\S]*\}/)[0]);
const [, , toolName, argsJson] = process.argv;
const child = spawn(cfg.command, cfg.args, { env: { ...process.env, GBRAIN_HOME: process.env.HOME }, stdio: ['pipe', 'pipe', 'inherit'] });
let buf = ''; const waiters = new Map(); let id = 0;
child.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i + 1); if (!line.trim()) continue; try { const m = JSON.parse(line); if (m.id != null && waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id); } } catch {} } });
const rpc = (method, params) => new Promise(r => { const n = ++id; waiters.set(n, r); child.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: n, method, params }) + '\n'); });
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
child.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
console.log('server:', JSON.stringify(init.result?.serverInfo));
const tools = await rpc('tools/list', {});
console.log('tools:', tools.result.tools.map(t => t.name).join(', '));
if (toolName) { const res = await rpc('tools/call', { name: toolName, arguments: JSON.parse(argsJson || '{}') }); console.log(toolName + ' ->', JSON.stringify(res.result ?? res.error).slice(0, 1500)); }
child.kill(); process.exit(0);

